{"id":"1136f044-e50d-4e24-b03f-4324974cc1df","inserted_at":"2026-04-28T14:45:24.803687+00:00","updated_at":"2026-04-28T14:45:24.803687+00:00","type":"sql","name":"Smart POI Retrieval with Null-Safe Routing","description":"","content":{"sql":"-- FIX: Assicuriamoci che i valori NULL non rompano l'algoritmo di Smart Routing\r\nDROP FUNCTION IF EXISTS get_smart_pois();\r\n\r\nCREATE FUNCTION get_smart_pois()\r\nRETURNS TABLE (\r\n    id UUID,\r\n    name TEXT,\r\n    category TEXT,\r\n    layer_name TEXT,\r\n    xp_reward INTEGER,\r\n    checkin_radius INTEGER,\r\n    crowd_level INTEGER,\r\n    has_water BOOLEAN,\r\n    alternative_poi_id UUID,\r\n    is_recommended BOOLEAN,\r\n    latitude FLOAT8,\r\n    longitude FLOAT8,\r\n    p_iva TEXT,\r\n    loto_quota_max INTEGER,\r\n    current_occupancy INTEGER,\r\n    pending_occupancy INTEGER\r\n) AS $$\r\nBEGIN\r\n    PERFORM the_reaper_cleanup();\r\n\r\n    RETURN QUERY\r\n    SELECT \r\n        p.id, \r\n        p.name, \r\n        p.category, \r\n        p.layer_name, \r\n        p.xp_reward, \r\n        p.checkin_radius,\r\n        p.crowd_level,\r\n        p.has_water,\r\n        p.alternative_poi_id,\r\n        p.is_recommended,\r\n        ST_Y(p.coords::geometry) as latitude,\r\n        ST_X(p.coords::geometry) as longitude,\r\n        p.p_iva,\r\n        COALESCE(p.loto_quota_max, 50) as loto_quota_max,\r\n        COALESCE(p.current_occupancy, 0) as current_occupancy,\r\n        COALESCE(p.pending_occupancy, 0) as pending_occupancy\r\n    FROM public.pois p\r\n    WHERE p.is_active = true\r\n    ORDER BY ((COALESCE(p.current_occupancy, 0) + COALESCE(p.pending_occupancy, 0))::float / GREATEST(COALESCE(p.loto_quota_max, 50), 1)) ASC, p.name ASC;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;\r\n","content_id":"1136f044-e50d-4e24-b03f-4324974cc1df","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
